.pc{max-width:1180px}.pc .panel{background:#fff;border:1px solid #e1e9e4;border-radius:12px;padding:18px;box-shadow:0 2px 8px rgba(18,59,42,.05);margin-bottom:14px}.pc h2,.pc h3{margin:0;color:#14213d}.pc .sub{margin:5px 0 14px;color:#667085;font-size:13px}.pc .form{display:grid;grid-template-columns:2fr 2fr auto auto;gap:10px;align-items:end}.pc label{display:block;font-weight:650;color:#344054;font-size:13px;margin-bottom:5px}.pc input{width:100%;padding:10px;border:1px solid #cfdad3;border-radius:8px;font:inherit}.pc button{padding:10px 14px;border:1px solid #c7d0da;border-radius:8px;background:#fff;color:#17365d;font-weight:650;cursor:pointer}.pc button.primary{background:#17365d;border-color:#17365d;color:#fff}.pc .ports{display:flex;gap:6px;flex-wrap:wrap}.pc .port{padding:5px 9px;border:1px solid #d8e0db;border-radius:999px;background:#f7f9f8;cursor:pointer;font-size:12px}.pc .port input{width:auto;margin-right:4px}.pc .actions{display:flex;gap:8px;margin-top:12px}.pc .summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}.pc .stat{border:1px solid #e1e9e4;border-radius:9px;padding:12px;background:#f8faf9}.pc .stat strong{display:block;font-size:20px;color:#17365d}.pc .stat span{font-size:12px;color:#667085}.pc .table-wrap{overflow:auto;border:1px solid #e1e9e4;border-radius:9px}.pc table{width:100%;border-collapse:collapse;font-size:13px}.pc th,.pc td{padding:9px;border:1px solid #e1e9e4;text-align:left}.pc th{background:#f3f6f4;color:#344054}.pc .open{color:#16794a;font-weight:700}.pc .closed{color:#667085;font-weight:700}.pc .timeout,.pc .error{color:#b42318;font-weight:700}.pc .mono{font-family:ui-monospace,monospace}.pc .note{padding:10px 12px;background:#fff8e7;border:1px solid #ead89b;border-radius:8px;color:#735b00;font-size:12px}@media(max-width:800px){.pc .form{grid-template-columns:1fr}.pc .summary{grid-template-columns:1fr 1fr}}
